// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Net;
using System.Net.Sockets;

namespace Campground.Shared.Network
{
    /// <summary>Where a request came from.</summary>
    internal enum NetworkClass
    {
        Local,
        Remote,
        Vpn,
    }

    /// <summary>The network settings the classifier needs, read from Jellyfin (see <see cref="JellyfinNetworkSettings"/>).</summary>
    internal sealed record NetworkSettings(
        IReadOnlyList<string> LocalNetworkSubnets,
        IReadOnlyList<string> KnownProxies,
        IReadOnlyList<string> VpnRanges,
        string BaseUrl,
        bool RequireHttps,
        bool EnableHttps,
        IReadOnlyList<string> PublishedServerUris);

    /// <summary>The answer for one request.</summary>
    /// <param name="JellyfinLocal">
    /// Exactly what Jellyfin's <c>INetworkManager.IsInLocalNetwork</c> answers for <see cref="ClientAddress"/>, with
    /// no VPN ranges applied (false when the client is unknown). Use it where a plugin must agree with Jellyfin,
    /// such as Bonfire's PIN bypass. <see cref="Class"/> is the Campground view, where a VPN range wins.
    /// </param>
    internal sealed record Classification(
        NetworkClass Class,
        IPAddress? ClientAddress,
        bool ViaProxy,
        bool ProxyTrusted,
        bool ForwardedProtoHttps,
        bool JellyfinLocal = false);

    /// <summary>
    /// §3.4 — one answer to "is this request local, remote, or through a VPN?" for every plugin.
    /// Pure logic; feed it the connection address, the forwarding headers and <see cref="NetworkSettings"/>.
    /// The local/remote part mirrors Jellyfin 10.11–12.x (NetworkManager.InitializeLan and IsInLocalNetwork, and
    /// ConfigureForwardHeaders for Known proxies); NetworkTests pins each rule.
    /// </summary>
    internal static class NetworkClassifier
    {
        // Jellyfin's LAN when LocalNetworkSubnets has no usable entries. No IPv4 link-local (169.254/16): Jellyfin
        // doesn't count it. fe80::/10 is in (Jellyfin calls it "IPv6RFC4291SiteLocal").
        private static readonly IPNetwork[] JellyfinFallbackLan =
        {
            IPNetwork.Parse("::1/128"),
            IPNetwork.Parse("fe80::/10"),
            IPNetwork.Parse("fc00::/7"),
            IPNetwork.Parse("127.0.0.0/8"),
            IPNetwork.Parse("10.0.0.0/8"),
            IPNetwork.Parse("172.16.0.0/12"),
            IPNetwork.Parse("192.168.0.0/16"),
        };

        // ASP.NET's ForwardedHeadersOptions defaults. Jellyfin adds Known proxies to them without clearing them,
        // so once Known proxies has any entry, loopback is trusted too. With an empty list, nothing is trusted.
        private static readonly IPNetwork[] AspNetDefaultProxies =
        {
            IPNetwork.Parse("127.0.0.0/8"),
            IPNetwork.Parse("::1/128"),
        };

        // "Near" addresses for the proxy check: anything a reverse proxy on the LAN could have.
        private static readonly IPNetwork[] NearAddresses = JellyfinFallbackLan
            .Append(IPNetwork.Parse("169.254.0.0/16"))
            .ToArray();

        /// <summary>
        /// Classifies a request. <paramref name="forwardedFor"/> is honoured only when the connection comes
        /// from a trusted proxy (as Jellyfin trusts them); otherwise anyone could claim to be local.
        /// </summary>
        internal static Classification Classify(
            IPAddress? connection,
            string? forwardedFor,
            string? forwardedProto,
            NetworkSettings settings)
        {
            var conn = Normalize(connection);
            var proxies = TrustedProxies(settings.KnownProxies);
            var viaProxy = !string.IsNullOrWhiteSpace(forwardedFor);
            var trusted = conn != null && proxies.Any(n => n.Contains(conn));

            var client = conn;
            if (viaProxy && trusted)
            {
                client = FirstUntrustedHop(forwardedFor!, proxies) ?? conn;
            }

            var https = trusted && string.Equals(forwardedProto?.Split(',')[0].Trim(), "https", StringComparison.OrdinalIgnoreCase);

            if (client == null)
            {
                return new Classification(NetworkClass.Remote, null, viaProxy, trusted, https, false);
            }

            var jellyfinLocal = IsJellyfinLocal(client, settings.LocalNetworkSubnets);
            var vpn = ParseNetworks(settings.VpnRanges);
            if (vpn.Any(n => n.Contains(client)))
            {
                return new Classification(NetworkClass.Vpn, client, viaProxy, trusted, https, jellyfinLocal);
            }

            return new Classification(jellyfinLocal ? NetworkClass.Local : NetworkClass.Remote, client, viaProxy, trusted, https, jellyfinLocal);
        }

        /// <summary>
        /// Jellyfin's IsInLocalNetwork: loopback is always local; otherwise the address must be in the LAN
        /// (LocalNetworkSubnets, or the private ranges when it has no usable entries) and not in a "!" exclusion.
        /// </summary>
        internal static bool IsJellyfinLocal(IPAddress address, IReadOnlyList<string>? localNetworkSubnets)
        {
            var ip = Normalize(address)!;
            if (IPAddress.IsLoopback(ip))
            {
                return true;
            }

            var entries = localNetworkSubnets ?? Array.Empty<string>();
            var lan = ParseNetworks(entries.Where(e => !IsExclusion(e)));
            var excluded = ParseNetworks(entries.Where(IsExclusion).Select(e => e.Trim()[1..]));
            return (lan.Count > 0 ? lan : JellyfinFallbackLan).Any(n => n.Contains(ip)) && !excluded.Any(n => n.Contains(ip));
        }

        /// <summary>
        /// The proxies Jellyfin trusts for X-Forwarded-For: none when Known proxies is empty, else those plus loopback.
        /// Not mirrored: Jellyfin also resolves host names listed there (DNS); this skips them.
        /// </summary>
        internal static IReadOnlyList<IPNetwork> TrustedProxies(IReadOnlyList<string>? knownProxies)
            => knownProxies == null || knownProxies.Count == 0
                ? Array.Empty<IPNetwork>()
                : ParseNetworks(knownProxies).Concat(AspNetDefaultProxies).ToList();

        private static bool IsExclusion(string? entry) => (entry ?? string.Empty).TrimStart().StartsWith('!');

        /// <summary>
        /// The proxy problem: requests carry X-Forwarded-For from a loopback or LAN address, but Known proxies is
        /// empty (or doesn't include that address), so Jellyfin sees every remote user as local.
        /// </summary>
        internal static bool IsUntrustedProxyProblem(IPAddress? connection, string? forwardedFor, NetworkSettings settings)
        {
            var conn = Normalize(connection);
            if (conn == null || string.IsNullOrWhiteSpace(forwardedFor))
            {
                return false;
            }

            var isNear = IPAddress.IsLoopback(conn) || NearAddresses.Any(n => n.Contains(conn));
            var trusted = TrustedProxies(settings.KnownProxies).Any(n => n.Contains(conn));
            return isNear && !trusted;
        }

        /// <summary>Parses addresses and CIDR ranges; bad entries are skipped.</summary>
        internal static IReadOnlyList<IPNetwork> ParseNetworks(IEnumerable<string>? entries)
        {
            var list = new List<IPNetwork>();
            foreach (var raw in entries ?? Array.Empty<string>())
            {
                var s = (raw ?? string.Empty).Trim();
                if (s.Length == 0)
                {
                    continue;
                }

                if (s.Contains('/', StringComparison.Ordinal) && IPNetwork.TryParse(s, out var net))
                {
                    list.Add(net);
                }
                else if (IPAddress.TryParse(s, out var ip))
                {
                    ip = Normalize(ip)!;
                    list.Add(new IPNetwork(ip, ip.AddressFamily == AddressFamily.InterNetwork ? 32 : 128));
                }
            }

            return list;
        }

        private static IPAddress? FirstUntrustedHop(string forwardedFor, IReadOnlyList<IPNetwork> proxies)
        {
            // Right to left: the nearest hop that isn't one of our proxies is the client.
            var hops = forwardedFor.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            for (var i = hops.Length - 1; i >= 0; i--)
            {
                var hop = hops[i];
                if (hop.StartsWith('[') && hop.Contains(']', StringComparison.Ordinal))
                {
                    hop = hop[1..hop.IndexOf(']', StringComparison.Ordinal)];
                }
                else if (hop.Count(c => c == ':') == 1)
                {
                    hop = hop[..hop.IndexOf(':', StringComparison.Ordinal)];
                }

                if (!IPAddress.TryParse(hop, out var ip))
                {
                    continue;
                }

                ip = Normalize(ip)!;
                if (!proxies.Any(n => n.Contains(ip)))
                {
                    return ip;
                }
            }

            return null;
        }

        private static IPAddress? Normalize(IPAddress? ip)
            => ip is { IsIPv4MappedToIPv6: true } ? ip.MapToIPv4() : ip;
    }
}
